This Terraform configuration creates an Amazon Lightsail instance with dual-stack networking enabled, meaning it can use both IPv4 and IPv6. It provisions a small Ubuntu Lightsail instance in a valid AWS region and outputs its instance name, public IPv4 address, and public IPv6 addresses.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "lightsail_instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "dualstack-lightsail-instance"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail instance."
  type        = string
  default     = "us-east-1a"
}

variable "blueprint_id" {
  description = "Lightsail blueprint ID."
  type        = string
  default     = "ubuntu_22_04"
}

variable "bundle_id" {
  description = "Lightsail bundle ID."
  type        = string
  default     = "nano_3_0"
}

